SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, [Станции_89-2020].YEAR, [Станции_89-2020].NUST, [nr], [Станции_89-2020].E, [Станции_89-2020].eotp, [Станции_89-2020].eurt, [Станции_89-2020].eust, [Станции_89-2020].Q, [Станции_89-2020].turt, [Станции_89-2020].tust, [Станции_89-2020].b, [Станции_89-2020].gaz, [Станции_89-2020].mazut, [Станции_89-2020].torf, [Станции_89-2020].slan, [Станции_89-2020].gtt, [Станции_89-2020].proch, [Станции_89-2020].ugol, [Станции_89-2020].don, [Станции_89-2020].podm, [Станции_89-2020].pech, [Доп_угли99-2000].int, [Доп_угли99-2000].vork, [Станции_89-2020].arkt, [Станции_89-2020].kuzn, [Станции_89-2020].ural, [Доп_угли99-2000].sver, [Доп_угли99-2000].chel, [Доп_угли99-2000].kizel, [Станции_89-2020].bashk, [Станции_89-2020].ekib, [Станции_89-2020].karag, [Станции_89-2020].kan, [Доп_угли99-2000].nazar, [Доп_угли99-2000].ibor, [Доп_угли99-2000].berez, [Доп_угли99-2000].per, [Станции_89-2020].irkut, [Доп_угли99-2000].azey, [Доп_угли99-2000].cher, [Станции_89-2020].hak, [Станции_89-2020].tuv, [Станции_89-2020].bur, [Доп_угли99-2000].gusin, [Доп_угли99-2000].tugn, [Станции_89-2020].chit, [Станции_89-2020].ner, [Станции_89-2020].raich, [Станции_89-2020].urg, [Станции_89-2020].prim, [Станции_89-2020].luch, [Станции_89-2020].mag, [Станции_89-2020].sah, [Станции_89-2020].qotr, [Станции_89-2020].snk, [Станции_89-2020].ewtp, [Станции_89-2020].NT, [Станции_89-2020].obor, [Станции_89-2020].VED, [Станции_89-2020].OBL, [Станции_89-2020].DEP, [Станции_89-2020].OES, [Станции_89-2020].ER, [Станции_89-2020].NUMB1120, IIf([ved]<3,1,2) AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,1,0) AS [sum]
FROM ((([Станции_89-2020] INNER JOIN Имена_станций ON [Станции_89-2020].NUMB1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON [Станции_89-2020].OES=Имена_ОЭС.oes) INNER JOIN Имена_областей ON [Станции_89-2020].OBL=Имена_областей.OBL) LEFT JOIN [Доп_угли99-2000] ON ([Станции_89-2020].NUMB1120=[Доп_угли99-2000].NUMB1120) AND ([Станции_89-2020].YEAR=[Доп_угли99-2000].YEAR);
